package dev.gravaai.services.recording;

import java.nio.file.Path;
import java.util.regex.Pattern;

/** Library sequence sources, ported from {@code electron/ipc/recording/sequenceSource.ts}. */
public final class SequenceSource {

	private static final Pattern LIBRARY_SOURCE_NAME =
			Pattern.compile("^[0-9a-f-]{36}\\.mp4$");

	private SequenceSource() {
	}

	/** Sources generated by Videos imports have independent, lossless audio companions. */
	public static boolean isLibrarySequenceSource(String file) {
		if (file == null) {
			return false;
		}
		Path path = Path.of(file);
		Path parent = path.getParent();
		return parent != null
				&& ".gravaai-media".equals(parent.getFileName() == null ? null : parent.getFileName().toString())
				&& LIBRARY_SOURCE_NAME.matcher(path.getFileName().toString()).matches();
	}
}
